Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    // Fetch valid retailer ids referenced
    const retailerIds = [...new Set(ORDERS.map((o:any)=>o.retailer_id).filter(Boolean))];
    const cancelledByIds = [...new Set(ORDERS.map((o:any)=>o.cancelled_by).filter(Boolean))];

    const validRetailers = new Set<string>();
    for (let i=0; i<retailerIds.length; i+=100) {
      const chunk = retailerIds.slice(i, i+100);
      const { data, error } = await supabase.from("retailers").select("id").in("id", chunk);
      if (error) throw error;
      data?.forEach((r:any)=>validRetailers.add(r.id));
    }
    const validProfiles = new Set<string>();
    if (cancelledByIds.length) {
      const { data, error } = await supabase.from("profiles").select("id").in("id", cancelledByIds);
      if (error) throw error;
      data?.forEach((r:any)=>validProfiles.add(r.id));
    }

    // Existing order ids (collision check)
    const orderIds = ORDERS.map((o:any)=>o.id);
    const existing = new Set<string>();
    for (let i=0; i<orderIds.length; i+=100) {
      const chunk = orderIds.slice(i, i+100);
      const { data, error } = await supabase.from("orders").select("id").in("id", chunk);
      if (error) throw error;
      data?.forEach((r:any)=>existing.add(r.id));
    }

    const toInsert = ORDERS
      .filter((o:any)=>!existing.has(o.id))
      .map((o:any)=>({
        ...o,
        retailer_id: o.retailer_id && validRetailers.has(o.retailer_id) ? o.retailer_id : null,
        cancelled_by: o.cancelled_by && validProfiles.has(o.cancelled_by) ? o.cancelled_by : null,
        // strip FK-risky fields we don't validate (CSV had them all null anyway)
        counter_customer_id: null,
        event_id: null,
      }));

    let inserted = 0;
    const errors:any[] = [];
    for (let i=0; i<toInsert.length; i+=100) {
      const chunk = toInsert.slice(i, i+100);
      const { error, count } = await supabase.from("orders").insert(chunk, { count: "exact" });
      if (error) { errors.push({ batch: i, error: error.message }); }
      else inserted += chunk.length;
    }

    // Post-verify
    const { count: finalCount } = await supabase.from("orders")
      .select("id", { count: "exact", head: true })
      .eq("user_id", "6220fc85-ae7f-4c22-9694-db6c47fe8fb0");

    return new Response(JSON.stringify({
      source_rows: ORDERS.length,
      already_existed: existing.size,
      valid_retailer_refs: validRetailers.size,
      valid_profile_refs: validProfiles.size,
      attempted: toInsert.length,
      inserted,
      errors,
      sardar_orders_total_now: finalCount,
    }, null, 2), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
  } catch (e:any) {
    return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
});
